/* Tank Battle: independent deterministic simulation, no DOM or other mode state. */
(function(root){'use strict';
const TILE=16,CELLS=26,SIZE=TILE*CELLS,DIRS=[[0,-1],[1,0],[0,1],[-1,0]];
const HEROES={explorer:{name:'PIXEL EXPLORER',cn:'冒险家',color:'#ed7251',skill:'烈焰三连炮',tip:'三发爆破炮，炸开砖墙'},soldier:{name:'COMMANDO',cn:'魂斗罗',color:'#94bd6e',skill:'火力压制',tip:'扇形齐射，8 秒极速装填'},mystic:{name:'THREE-EYED KID',cn:'三目童子',color:'#a891e8',skill:'回旋光箭',tip:'贯穿光箭，沿原路返回'},dora:{name:'DORAEMON',cn:'哆啦A梦',color:'#57c9ec',skill:'空气护盾炮',tip:'贯穿空气炮，全队护盾 5 秒'},goku:{name:'SON GOKU',cn:'孙悟空',color:'#f5ad45',skill:'龟派气功',tip:'高伤害贯穿气功，短暂护盾'},nezha:{name:'NEZHA',cn:'哪吒',color:'#f184a5',skill:'乾坤回旋圈',tip:'回旋圈，加速 5 秒并获得护盾'}};
const MAPS=[
['.............','.BB.BB.BB.BB.','.SS...F...SS.','..F.BB.BB.F..','.............','.BB.WW.WW.BB.','..F.WW.WW.F..','.SS.BB.BB.SS.','.............','.BB.FF.FF.BB.','..S.B...B.S..','.............','.............'],
['.............','.BB.SS.SS.BB.','..F.BB.BB.F..','.WW...F...WW.','.............','.BB.WW.WW.BB.','..S.B...B.S..','.FF.BB.BB.FF.','.............','.SS.FF.FF.SS.','..B.S...S.B..','.............','.............'],
['.............','.SS.BB.BB.SS.','.FF...W...FF.','.BB.S...S.BB.','.............','.WW.BB.BB.WW.','..F.S...S.F..','.BB.BB.BB.BB.','.............','.SS.WW.WW.SS.','..B.F...F.B..','.............','.............'],
['.............','.BB.WW.WW.BB.','.SS...F...SS.','.FF.BB.BB.FF.','.............','.WW.SS.SS.WW.','..B.F...F.B..','.SS.BB.BB.SS.','.............','.BB.FF.FF.BB.','..F.S...S.F..','.............','.............'],
['.............','.FF.SS.SS.FF.','.BB...W...BB.','.SS.BB.BB.SS.','.............','.WW.FF.FF.WW.','..B.S...S.B..','.BB.WW.WW.BB.','.............','.SS.BB.BB.SS.','..F.F...F.F..','.............','.............'],
['.............','.SS.BB.BB.SS.','.WW...F...WW.','.BB.S...S.BB.','.............','.SS.FF.FF.SS.','..B.W...W.B..','.BB.SS.SS.BB.','.............','.FF.BB.BB.FF.','..S.F...F.S..','.............','.............']];
const LEVELS=['GREEN FRONTIER','RIVER CROSSING','IRON COMMANDER','TWILIGHT OUTPOST','FROZEN SIEGE','THE LAST BASTION'];
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
class Battle{
constructor(options={}){this.options={mode:'solo',p1:'explorer',p2:'dora',...options};this.seed=(options.seed??Date.now())>>>0;this.serial=0;this.score=0;this.level=0;this.paused=false;this.players=[this.player(0,this.options.p1)];if(this.options.mode==='coop')this.players.push(this.player(1,this.options.p2));this.events=[];this.load(0);}
random(){this.seed=(Math.imul(this.seed,1664525)+1013904223)>>>0;return this.seed/4294967296;}
player(side,id){return {id:HEROES[id]?id:'explorer',uid:++this.serial,side,player:true,x:side?240:176,y:336,w:22,dir:0,hp:2,maxHp:2,lives:3,weapon:1,energy:100,shield:3,cool:0,rapid:0,haste:0,shotFlash:0,respawn:0,alive:true,score:0,moving:false,tread:0};}
load(level){this.level=level;this.phase='ready';this.delay=2;this.tiles=Array(CELLS*CELLS).fill('.');for(let y=0;y<13;y++)for(let x=0;x<13;x++)for(let dy=0;dy<2;dy++)for(let dx=0;dx<2;dx++)this.tiles[(y*2+dy)*CELLS+x*2+dx]=MAPS[level][y][x];for(const [x,y]of [[5,11],[6,11],[7,11],[5,12],[7,12]])for(let dy=0;dy<2;dy++)for(let dx=0;dx<2;dx++)this.tiles[(y*2+dy)*CELLS+x*2+dx]='B';this.base={x:208,y:400,w:26,hp:3,maxHp:3,shield:10};this.enemies=[];this.shots=[];this.pickups=[];this.effects=[];this.freeze=0;this.bombFlash=0;this.spawnClock=.7;this.elapsed=0;this.kills=0;this.queue=Array.from({length:10+level*2},(_,i)=>i%5===4?'armor':i%3===2?'scout':i%4===3?'sniper':'grunt');if(level===2||level===5)this.queue.push('boss');for(const p of this.players){p.x=p.side?240:176;p.y=336;p.dir=0;p.hp=p.maxHp;p.alive=p.lives>0;p.respawn=0;p.cool=0;p.shield=3;p.energy=Math.max(70,p.energy);}this.events.push({type:'level',level});}
solid(x,y){if(x<0||y<0||x>=SIZE||y>=SIZE)return true;return ['B','S','W'].includes(this.tiles[Math.floor(y/TILE)*CELLS+Math.floor(x/TILE)]);}
canMove(t,x,y){const r=t.w/2-1;for(const [a,b]of [[-r,-r],[r,-r],[-r,r],[r,r],[0,-r],[0,r],[-r,0],[r,0]])if(this.solid(x+a,y+b))return false;if(Math.abs(x-this.base.x)<(t.w+this.base.w)/2&&Math.abs(y-this.base.y)<(t.w+this.base.w)/2)return false;return ![...this.players,...this.enemies].some(o=>o!==t&&o.alive&&Math.abs(o.x-x)<(o.w+t.w)/2-2&&Math.abs(o.y-y)<(o.w+t.w)/2-2);}
move(t,dir,speed,dt){if(dir%2!==t.dir%2){const x=dir%2?t.x:Math.round((t.x-16)/32)*32+16,y=dir%2?Math.round((t.y-16)/32)*32+16:t.y;if(Math.hypot(x-t.x,y-t.y)<=5&&this.canMove(t,x,y)){t.x=x;t.y=y;}}t.dir=dir;const [dx,dy]=DIRS[dir],x=t.x+dx*speed*dt,y=t.y+dy*speed*dt;t.moving=this.canMove(t,x,y);if(t.moving){t.x=x;t.y=y;t.tread+=dt*speed*.12;}return t.moving;}
spawn(){if(!this.queue.length)return;for(let k=0;k<3;k++){const col=[16,208,400][(Math.floor(this.random()*3)+k)%3];if([...this.enemies,...this.players].some(e=>e.alive&&Math.hypot(e.x-col,e.y-16)<38))continue;const type=this.queue.shift(),boss=type==='boss',hp=boss?14+this.level*2:type==='armor'?3:1,e={uid:++this.serial,id:type,type,player:false,x:col,y:16,w:boss?26:22,dir:2,hp,maxHp:hp,alive:true,shield:.75,cool:1.1,think:0,moveDir:2,stuck:0,shotFlash:0,tread:0,moving:false,speed:type==='scout'?83:boss?42:46+this.level*3};this.enemies.push(e);this.events.push({type:boss?'boss':'spawn',x:col,y:16});this.fx(col,16,'#a9e9fa',18);return;}}
fx(x,y,color,n=12){for(let i=0;i<n;i++){const a=this.random()*Math.PI*2,s=15+this.random()*70;this.effects.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25+this.random()*.35,color});}}
fire(t,{special=false,damage,angle=0,pierce=1,returning=false,color}={}){const [dx,dy]=DIRS[t.dir],a=Math.atan2(dy,dx)+angle;this.shots.push({uid:++this.serial,owner:t.uid,side:t.side,friendly:t.player,x:t.x+dx*(t.w/2+5),y:t.y+dy*(t.w/2+5),vx:Math.cos(a)*(special?300:255),vy:Math.sin(a)*(special?300:255),damage:damage??(t.player?(t.weapon>=2?2:1):t.type==='boss'?2:1),life:special?2.1:t.player?2.4:t.type==='sniper'||t.type==='boss'?1.6:1.05,age:0,hits:[],pierce,returning,returned:false,special,kind:special?t.id:'shell',color:color||(t.player?HEROES[t.id].color:'#ff9975')});t.shotFlash=.12;}
shoot(t){if(!t.alive||t.cool>0||t.shield>.1&&!t.player)return false;if(t.player&&this.shots.filter(s=>s.owner===t.uid&&!s.special).length>=(t.weapon>=2?4:2))return false;t.cool=t.player?(t.rapid>0?.10:t.weapon>=2?.25:.38):t.type==='boss'?.85:Math.max(.7,1.75-this.level*.14);this.fire(t);if(t.player&&t.weapon===3)this.fire(t,{angle:.10});if(!t.player&&t.type==='boss'){this.fire(t,{angle:-.2});this.fire(t,{angle:.2});}this.events.push({type:'shoot',side:t.side});return true;}
skill(p){if(!p.alive||p.energy<100)return false;p.energy=0;const col=HEROES[p.id].color;if(p.id==='explorer'){for(const a of [-.20,0,.20])this.fire(p,{special:true,damage:3,angle:a,color:col});}else if(p.id==='soldier'){p.rapid=8;for(const a of [-.3,-.15,0,.15,.3])this.fire(p,{special:true,damage:2,angle:a,color:col});}else if(p.id==='mystic'||p.id==='nezha'){this.fire(p,{special:true,damage:3,pierce:4,returning:true,color:col});if(p.id==='nezha'){p.haste=5;p.shield=Math.max(p.shield,2);}}else if(p.id==='dora'){for(const ally of this.players)if(ally.alive)ally.shield=Math.max(ally.shield,5);this.fire(p,{special:true,damage:3,pierce:3,color:col});}else if(p.id==='goku'){p.shield=Math.max(p.shield,2);this.fire(p,{special:true,damage:5,pierce:4,color:col});}this.fx(p.x,p.y,col,25);this.events.push({type:'skill',side:p.side,name:HEROES[p.id].skill});return true;}
hurt(t,damage,owner){if(!t.alive||t.shield>0)return false;t.hp-=damage;if(t.hp>0){t.shield=t.player?1.1:0;this.fx(t.x,t.y,'#fff5c5',6);return true;}t.alive=false;this.fx(t.x,t.y,t.player?HEROES[t.id].color:'#ffb34d',30);this.events.push({type:'explode',player:t.player});if(t.player){t.lives--;t.weapon=Math.max(1,t.weapon-1);t.respawn=t.lives>0?2:0;}else{this.kills++;const points=t.type==='boss'?2000:t.type==='armor'?300:t.type==='scout'?200:100;this.score+=points;const p=this.players.find(p=>p.uid===owner);if(p){p.score+=points;p.energy=clamp(p.energy+14,0,100);}if(this.kills%3===0||t.type==='boss')this.drop(t.x,t.y);}return true;}
drop(x,y,type){this.pickups.push({x,y,type:type||['weapon','shield','bomb','freeze','repair','life'][Math.floor(this.random()*6)],life:16});}
pickup(p,item){if(item.type==='weapon')p.weapon=Math.min(3,p.weapon+1);if(item.type==='shield')p.shield=8;if(item.type==='bomb'){for(const e of this.enemies)if(e.alive&&e.type!=='boss'){e.shield=0;this.hurt(e,e.hp,p.uid);}this.enemies=this.enemies.filter(e=>e.alive);this.shots=this.shots.filter(s=>s.friendly);this.bombFlash=.35;this.fx(p.x,p.y,'#fff2b0',40);this.events.push({type:'explode',player:false});}if(item.type==='freeze')this.freeze=6;if(item.type==='repair'){this.base.hp=Math.min(3,this.base.hp+1);this.base.shield=8;}if(item.type==='life'){p.lives=Math.min(5,p.lives+1);p.hp=p.maxHp;}p.energy=clamp(p.energy+25,0,100);item.life=0;this.events.push({type:'pickup',side:p.side,name:item.type});}
pathDir(e){const cx=clamp(Math.floor(e.x/32),0,12),cy=clamp(Math.floor(e.y/32),0,12),start=cy*13+cx,target=11*13+6,q=[start],seen=new Set([start]),first=new Map();for(let j=0;j<q.length;j++){const i=q[j],x=i%13,y=Math.floor(i/13);if(i===target)return first.get(i)??2;for(const d of [2,1,3,0]){const [dx,dy]=DIRS[d],nx=x+dx,ny=y+dy;if(nx<0||nx>=13||ny<0||ny>=13)continue;const n=ny*13+nx;if(seen.has(n))continue;let blocked=false;for(let a=0;a<2;a++)for(let b=0;b<2;b++)if(['S','W'].includes(this.tiles[(ny*2+b)*CELLS+nx*2+a]))blocked=true;if(blocked)continue;seen.add(n);first.set(n,first.get(i)??d);q.push(n);}}return 2;}
ai(e,dt){e.think-=dt;if(e.think<=0){e.think=.35+this.random()*.25;let dir=this.pathDir(e);const candidates=this.players.filter(p=>p.alive&&p.shield<.5);for(const p of [...candidates,this.base]){if(Math.abs(p.x-e.x)<15){dir=p.y>e.y?2:0;break;}if(Math.abs(p.y-e.y)<15){dir=p.x>e.x?1:3;break;}}if(e.stuck>.7){const possible=[0,1,2,3].filter(d=>{const [dx,dy]=DIRS[d];return this.canMove(e,e.x+dx*3,e.y+dy*3);});if(possible.length)dir=possible[Math.floor(this.random()*possible.length)];e.stuck=0;}if(dir%2!==e.dir%2){const axis=e.dir%2?e.x:e.y,center=Math.floor(axis/32)*32+16;if(Math.abs(axis-center)>2.5&&e.stuck<.4)dir=e.dir;}e.moveDir=dir;}const moved=this.move(e,e.moveDir,e.speed,dt);e.stuck=moved?0:e.stuck+dt;this.shoot(e);}
step(dt,inputs=[{},{}]){if(this.paused||['gameover','victory'].includes(this.phase))return;dt=clamp(dt,0,1/30);for(const f of this.effects){f.life-=dt;f.x+=f.vx*dt;f.y+=f.vy*dt;}this.effects=this.effects.filter(f=>f.life>0);if(this.phase==='ready'||this.phase==='clear'){this.delay-=dt;if(this.delay<=0){if(this.phase==='ready')this.phase='playing';else if(this.level===5){this.phase='victory';this.events.push({type:'victory'});}else this.load(this.level+1);}return;}this.bombFlash=Math.max(0,this.bombFlash-dt);this.elapsed+=dt;this.freeze=Math.max(0,this.freeze-dt);this.base.shield=Math.max(0,this.base.shield-dt);for(const t of [...this.players,...this.enemies]){t.cool=Math.max(0,t.cool-dt);t.shield=Math.max(0,t.shield-dt);t.shotFlash=Math.max(0,t.shotFlash-dt);t.moving=false;if(t.player){t.energy=clamp(t.energy+dt*7,0,100);t.rapid=Math.max(0,t.rapid-dt);t.haste=Math.max(0,t.haste-dt);if(!t.alive&&t.lives>0){t.respawn-=dt;if(t.respawn<=0){const x=t.side?240:176;if(this.canMove(t,x,336)){t.x=x;t.y=336;t.alive=true;t.hp=t.maxHp;t.dir=0;t.shield=3;}}}if(t.alive){const input=inputs[t.side]||{};if(input.dir!==undefined&&input.dir>=0)this.move(t,input.dir,t.haste>0?125:94,dt);if(input.fire)this.shoot(t);if(input.skill)this.skill(t);}}else if(t.alive&&this.freeze<=0)this.ai(t,dt);}
this.spawnClock-=dt;if(this.spawnClock<=0&&this.enemies.filter(e=>e.alive).length<(this.options.mode==='coop'?6:4)){this.spawn();this.spawnClock=Math.max(.8,2.4-this.level*.17);}
for(const s of this.shots){s.age+=dt;s.life-=dt;if(s.returning&&s.age>.75&&!s.returned){s.vx*=-1;s.vy*=-1;s.returned=true;}const steps=Math.max(1,Math.ceil(Math.hypot(s.vx,s.vy)*dt/5));for(let n=0;n<steps&&s.life>0;n++){s.x+=s.vx*dt/steps;s.y+=s.vy*dt/steps;if(s.x<0||s.y<0||s.x>=SIZE||s.y>=SIZE){s.life=0;break;}const i=Math.floor(s.y/TILE)*CELLS+Math.floor(s.x/TILE),tile=this.tiles[i];if(tile==='S'){s.life=0;this.fx(s.x,s.y,'#a8bfcd',4);break;}if(tile==='B'){this.tiles[i]='.';this.fx(s.x,s.y,'#c77f56',7);if(!(s.special&&s.pierce>1)){s.life=0;break;}}
if(!s.friendly&&Math.abs(s.x-this.base.x)<15&&Math.abs(s.y-this.base.y)<15){if(this.base.shield<=0)this.base.hp=Math.max(0,this.base.hp-s.damage);s.life=0;this.fx(this.base.x,this.base.y,'#ffb64d',20);this.events.push({type:'basehit'});break;}const targets=s.friendly?this.enemies:this.players;for(const t of targets){if(!t.alive||s.hits.includes(t.uid)||Math.abs(s.x-t.x)>t.w/2+3||Math.abs(s.y-t.y)>t.w/2+3)continue;s.hits.push(t.uid);this.hurt(t,s.damage,s.owner);if(s.hits.length>=s.pierce)s.life=0;break;}}
}
for(let i=0;i<this.shots.length;i++){const a=this.shots[i];if(a.life<=0)continue;for(let j=i+1;j<this.shots.length;j++){const b=this.shots[j];if(a.friendly!==b.friendly&&b.life>0&&Math.hypot(a.x-b.x,a.y-b.y)<8){a.life=b.life=0;this.fx(a.x,a.y,'#fff5cf',5);break;}}}this.shots=this.shots.filter(s=>s.life>0);this.enemies=this.enemies.filter(e=>e.alive);for(const item of this.pickups){item.life-=dt;for(const p of this.players)if(p.alive&&Math.hypot(p.x-item.x,p.y-item.y)<20){this.pickup(p,item);break;}}this.pickups=this.pickups.filter(p=>p.life>0);if(this.base.hp===0||this.players.every(p=>p.lives===0)){this.phase='gameover';this.events.push({type:'gameover'});}else if(!this.queue.length&&!this.enemies.length){this.phase='clear';this.delay=3;this.events.push({type:'clear'});}}
snapshot(){return {phase:this.phase,level:this.level,score:this.score,base:{...this.base},remaining:this.queue.length+this.enemies.length,players:this.players.map(p=>({...p})),enemies:this.enemies.map(e=>({...e})),shots:this.shots.length,paused:this.paused};}
}
const api={Battle,HEROES,MAPS,LEVELS,TILE,CELLS,SIZE,DIRS};root.PixelTankCore=api;if(typeof module==='object')module.exports=api;
})(typeof globalThis==='object'?globalThis:this);
